 ("16523","2024-05-04 21:30","2024-05-05 03:00",False,"Beach Party 2024",LEG,"","","2024/04/FACEBOOK-Beach-Party-3.jpg",""),
 ("journee-des-petits-entrepreneurs","2024-06-01 10:00","2024-06-01 15:00",False,"Journée des petits entrepreneurs","Carrefour Gaspé","","","2024/05/IMG_3348.jpeg","<p>Le Club Entrepreneur Étudiant de Gaspé est fier de participer à la Journée des petits entrepreneurs organisée par la Chambre de commerce, qui se déroulera au Carrefour Gaspé. Lors de cet événement, nous serons présents pour soutenir et guider les jeunes entrepreneurs de notre communauté. Notre objectif est d’inspirer la prochaine génération de leaders et de les aider à concrétiser leurs idées innovantes.</p>"),
 ("fox-party-2-0","2024-06-08 22:00","2024-06-09 03:00",False,"Fox Party 2.0",APO,"7 $","","2024/05/443716063_775895857976098_3707684627319360449_n-1.jpg",""),
 ("back-to-school-party-dj-nosense-dj-nitro-la-voute","2024-09-07 20:30","2024-09-08 03:00",False,"Back to school party – DJ Nosense – DJ Nitro à La Voûte",LV,"5 $",FB+"1056269889182025","2024/09/Back-to-school-le-bon.png","<p>🎉 <strong>Célébrons la rentrée scolaire avec le Club Entrepreneur !</strong> 🎉</p><p>🎧 Au programme : <strong>DJ Nitro</strong> et <strong>DJ Nosense</strong> pour une ambiance musicale au top. Rejoignez-nous pour une soirée festive et conviviale : c’est l’occasion idéale pour démarrer l’année scolaire en beauté. Invitez vos amis ! 🎓🥂</p>"),
 ("bingo-legion-canadienne-de-gaspe-17-septembre","2024-09-17 19:00","2024-09-17 21:00",False,"Bingo – Légion canadienne de Gaspé",LEG,"",FB+"846403500948816","2024/09/bingo-web.png",""),
 ("soiree-dj-dj-nosense-28-septembre-bar-apollo","2024-09-28 22:00","2024-09-29 03:00",False,"Soirée DJ – DJ Nosense – Bar Apollo",APO,"10 $",FB+"1363011595085645/","2024/09/soiree-Dj.png","<p>🔥 <strong>Soirée DJ avec DJ NoSense</strong> 🔥 Viens bouger avec nous au Bar Apollo à Rivière-au-Renard, le 28 septembre à 22h00 ! 🎧🎶 Entrée : 10 $. Tous les profits iront au Club Entrepreneur, qui organise l’événement.</p>"),
